282	// GATE SCAN — FM only: scan/verify a driver pass by booking_ref at the bay.
283	//   body: { action: 'entry' | 'exit', observedPlate?: string }
284	//   entry: Pending/Confirmed → Arrived (+ WhatsApp arrival)
285	//   exit:  Arrived/Confirmed → Completed (+ WhatsApp completed + next-in-line)
286	// Plate mismatch is flagged (warn) but does not block. WhatsApp is non-fatal.
287	// ---------------------------------------------------------------------------
288	router.patch('/:ref/gate-scan', verifyToken, requireRole('FM'), async (req, res) => {
289	    try {
290	        const { action, observedPlate } = req.body;
291	        if (!['entry', 'exit'].includes(action)) {
292	            return res.status(400).json({ error: "action must be 'entry' or 'exit'." });
293	        }
294	
295	        const booking = await Booking.findOne({ where: { booking_ref: req.params.ref } });
296	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
297	
298	        // Optional plate verification (warn-only — never blocks the scan).
299	        let plateMatched = null;
300	        if (observedPlate && String(observedPlate).trim()) {
301	            const norm = (s) => String(s || '').toUpperCase().replace(/\s+/g, '');
302	            plateMatched = norm(observedPlate) === norm(booking.license_plate);
303	        }
304	
305	        let whatsappStatus = null;
306	        let nextInLine = null;
307	
308	        if (action === 'entry') {
309	            if (booking.status === 'Cancelled' || booking.status === 'Completed') {
310	                return res.status(409).json({ error: `Cannot mark arrival: booking is ${booking.status}.`, booking, plateMatched });
311	            }
312	            await booking.update({ status: 'Arrived', arrived_at: new Date() });
313	            try {
314	                whatsappStatus = await whatsapp.sendBookingArrived(booking);
315	            } catch (waErr) {
316	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
317	            }
318	        } else { // exit
319	            if (booking.status === 'Cancelled') {
320	                return res.status(409).json({ error: 'Cannot mark exit: booking is Cancelled.', booking, plateMatched });
321	            }
322	            if (booking.status === 'Completed') {
323	                // Idempotent — already completed, do not re-notify / re-trigger next-in-line.
324	                return res.status(200).json({
325	                    message: 'Booking already completed.', booking, action,
326	                    plateMatched, whatsappStatus: null, nextInLine: null, alreadyCompleted: true
327	                });
328	            }
329	            await booking.update({ status: 'Completed', completed_at: new Date() });
330	            try {
331	                whatsappStatus = await whatsapp.sendBookingCompleted(booking);
332	                const next = await Booking.findOne({
333	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
334	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
335	                });
336	                if (next) {
337	                    await whatsapp.sendNextInLine(next);
338	                    nextInLine = next.booking_ref;
339	                }
340	            } catch (waErr) {
341	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
342	            }
343	        }
344	
345	        return res.status(200).json({
346	            message: `Gate ${action} recorded.`, booking, action, plateMatched, whatsappStatus, nextInLine
347	        });
348	    } catch (err) {
349	        console.error('Gate scan error:', err);
350	        return res.status(500).json({ error: 'Could not process gate scan.' });
351	    }
352	});
353	
354	// ---------------------------------------------------------------------------
355	// PUBLIC — driver pass lookup by booking_ref. NO auth (driver has no login).
356	// MUST stay last so it doesn't shadow '/all' or '/'.
357	// ---------------------------------------------------------------------------
358	router.get('/:ref', async (req, res) => {
359	    try {
360	        const booking = await Booking.findOne({ where: { booking_ref: req.params.ref } });
361	        if (!booking) return res.status(404).json({ message: 'Booking not found' });
362	
363	        // SAFE public DTO — only what the driver pass needs. Never expose
364	        // tenantId, driver_phone, private notes, or internal timestamps.
365	        res.json({
366	            booking_ref: booking.booking_ref,
367	            transport_company: booking.transport_company,
368	            driver_name: booking.driver_name,
369	            license_plate: booking.license_plate,
370	            loading_bay: booking.loading_bay,
371	            slot_start: booking.slot_start,
372	            slot_end: booking.slot_end,
373	            status: booking.status,
374	            arrived_at: booking.arrived_at,
375	            completed_at: booking.completed_at
376	        });
377	    } catch (err) {
378	        console.error('Booking lookup error:', err);
379	        res.status(500).json({ message: 'Error fetching booking' });
380	    }
381	});
382	
383	module.exports = router;
