2	import axios from 'axios';
3	import Sidebar from '../components/Sidebar';
4	import '../css/Dashboard.css';
5	import '../css/Management.css';
6	import '../css/Booking.css';
7	import { API_BASE_URL } from '../constants/api';
8	
9	const BAYS = ['Bay A', 'Bay B'];
10	const STATUSES = ['Pending', 'Confirmed', 'Arrived', 'Completed', 'Cancelled'];
11	const STATUS_FLOW = { Pending: 'Confirmed', Confirmed: 'Arrived', Arrived: 'Completed' };
12	const CLOSED = ['Completed', 'Cancelled'];
13	
14	const emptyForm = {
15	  transport_company: '', license_plate: '', driver_phone: '',
16	  driver_name: '', loading_bay: '', slot_start: '', slot_end: '', notes: ''
17	};
18	
19	const TenantLogistics = () => {
20	  const [bookings, setBookings] = useState([]);
21	  const [loading, setLoading] = useState(true);
22	  const [error, setError] = useState('');
23	  const [notice, setNotice] = useState('');
24	  const [form, setForm] = useState(emptyForm);
25	  const [submitting, setSubmitting] = useState(false);
26	
27	  // Booking form is hidden by default and opens in a modal (keeps the list roomy).
28	  const [isFormOpen, setIsFormOpen] = useState(false);
29	  // Manual UPDATE evidence: when set, the modal edits this booking via PATCH /api/bookings/:id.
30	  const [editingId, setEditingId] = useState(null);
31	  // Frontend-only filtering (backend has no booking filter endpoint).
32	  const [searchText, setSearchText] = useState('');
33	  const [filterStatus, setFilterStatus] = useState('All');
34	  const [filterBay, setFilterBay] = useState('All');
35	  const [filterDate, setFilterDate] = useState(''); // YYYY-MM-DD; empty = all dates
36	
37	  // Gate Scan (FM/Staff) — verify a driver pass by booking ref at the loading bay.
38	  const [gateOpen, setGateOpen] = useState(false);
39	  const [gateRef, setGateRef] = useState('');
40	  const [gatePlate, setGatePlate] = useState('');
41	  const [gateBusy, setGateBusy] = useState(false);
42	  const [gateError, setGateError] = useState('');
43	
44	  const token = localStorage.getItem('accessToken');
45	  const role = localStorage.getItem('userRole');
46	  const authHeader = { headers: { Authorization: `Bearer ${token}` } };
47	
48	  const canManage = role === 'FM';                                    // status updates (facility-level) — FM only
49	  const canGateScan = role === 'FM';                                  // gate entry/exit — FM only
50	  const canCreate = role === 'FM' || role === 'Tenant' || role === 'Staff'; // create bookings (Staff books for their unit)
51	
52	  const fetchBookings = async () => {
53	    setLoading(true);
54	    setError('');
55	    try {
56	      const res = await axios.get(`${API_BASE_URL}/api/bookings/`, authHeader);
57	      setBookings(Array.isArray(res.data) ? res.data : []);
58	    } catch (err) {
59	      console.error('Failed to fetch bookings:', err);
60	      setError('Could not load bookings. Please try again.');
61	      setBookings([]);
62	    } finally {
63	      setLoading(false);
64	    }
65	  };
66	
67	  useEffect(() => { fetchBookings(); }, []);
68	
69	  useEffect(() => {
70	    if (!notice) return;
71	    const t = setTimeout(() => setNotice(''), 5000);
72	    return () => clearTimeout(t);
73	  }, [notice]);
74	
75	  const onField = (e) => setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
76	
77	  const openForm = () => { setError(''); setForm(emptyForm); setEditingId(null); setIsFormOpen(true); };
78	  const closeForm = () => { setIsFormOpen(false); setEditingId(null); };
79	
80	  // ISO/DB timestamp → value accepted by <input type="datetime-local">.
81	  const toLocalInput = (v) => {
82	    if (!v) return '';
83	    const d = new Date(v);
84	    if (isNaN(d.getTime())) return '';
85	    const p = (n) => String(n).padStart(2, '0');
86	    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
87	  };
88	
89	  const openEdit = (b) => {
90	    setError('');
91	    setForm({
92	      transport_company: b.transport_company || '',
93	      license_plate: b.license_plate || '',
94	      driver_phone: b.driver_phone || '',
95	      driver_name: b.driver_name || '',
96	      loading_bay: b.loading_bay || '',
97	      slot_start: toLocalInput(b.slot_start),
98	      slot_end: toLocalInput(b.slot_end),
99	      notes: b.notes || ''
100	    });
101	    setEditingId(b.id);
102	    setIsFormOpen(true);
103	  };
104	
105	  const describeWhatsapp = (wa) => {
106	    if (!wa) return '';
107	    if (wa.simulated) return ' (WhatsApp simulated — disabled)';
108	    return wa.success ? ' (WhatsApp sent)' : ' (WhatsApp delivery pending)';
109	  };
110	
111	  const submitBookingForm = async (e) => {
112	    e.preventDefault();
113	    setSubmitting(true);
114	    setError('');
115	    try {
116	      if (editingId) {
117	        // Manual UPDATE — editable fields only; server enforces ownership + slot conflicts.
118	        await axios.patch(`${API_BASE_URL}/api/bookings/${editingId}`, form, authHeader);
119	        setNotice('Booking updated.');
120	      } else {
121	        const res = await axios.post(`${API_BASE_URL}/api/bookings/create`, form, authHeader);
122	        setNotice(`Booking created (status: Pending).${describeWhatsapp(res.data?.whatsapp)}`);
123	      }
124	      setForm(emptyForm);
125	      setIsFormOpen(false);
126	      setEditingId(null);
127	      fetchBookings();
128	    } catch (err) {
129	      const msg = err.response?.data?.error || (editingId ? 'Failed to update booking.' : 'Failed to create booking.');
130	      setError(msg);
131	    } finally {
132	      setSubmitting(false);
133	    }
134	  };
135	
136	  const updateStatus = async (id, status) => {
137	    try {
138	      const res = await axios.patch(`${API_BASE_URL}/api/bookings/${id}/status`, { status }, authHeader);
139	      setNotice(`Booking ${status}.${describeWhatsapp(res.data?.whatsapp)}`);
140	      fetchBookings();
141	    } catch (err) {
142	      setError(err.response?.data?.error || 'Failed to update status.');
143	    }
144	  };
145	
146	  const cancelBooking = async (id) => {
147	    try {
148	      const res = await axios.patch(`${API_BASE_URL}/api/bookings/${id}/cancel`, {}, authHeader);
149	      setNotice(`Booking cancelled.${describeWhatsapp(res.data?.whatsapp)}`);
150	      fetchBookings();
151	    } catch (err) {
152	      setError(err.response?.data?.error || 'Failed to cancel booking.');
153	    }
154	  };
155	
156	  const openGate = () => { setGateError(''); setGateRef(''); setGatePlate(''); setGateOpen(true); };
157	  const closeGate = () => setGateOpen(false);
158	
159	  const gateScan = async (action) => {
160	    const ref = gateRef.trim();
161	    if (!ref) { setGateError('Enter a booking reference.'); return; }
162	    setGateBusy(true);
163	    setGateError('');
164	    try {
165	      const res = await axios.patch(
166	        `${API_BASE_URL}/api/bookings/${encodeURIComponent(ref)}/gate-scan`,
167	        { action, observedPlate: gatePlate.trim() || undefined },
168	        authHeader
169	      );
170	      const d = res.data || {};
171	      let msg = d.message || `Gate ${action} recorded.`;
172	      if (d.plateMatched === false) msg += ' ⚠ Plate mismatch — please verify the vehicle.';
173	      if (d.nextInLine) msg += ` Next in line: ${d.nextInLine}.`;
174	      msg += describeWhatsapp(d.whatsappStatus);
175	      setNotice(msg);
176	      setGateOpen(false);
177	      fetchBookings();
178	    } catch (err) {
179	      setGateError(err.response?.data?.error || 'Gate scan failed.');
180	    } finally {
181	      setGateBusy(false);
182	    }
183	  };
184	
185	  const fmtSlot = (b) => {
186	    if (!b.slot_start) return '—';
187	    try { return new Date(b.slot_start).toLocaleString('en-SG', { dateStyle: 'short', timeStyle: 'short' }); }
188	    catch { return b.slot_start; }
189	  };
190	
191	  // Local YYYY-MM-DD of a booking's slot start (matches the date input + displayed Slot).
192	  const slotDateKey = (b) => {
193	    if (!b.slot_start) return '';
194	    const d = new Date(b.slot_start);
195	    if (isNaN(d.getTime())) return String(b.slot_start).slice(0, 10);
196	    const p = (n) => String(n).padStart(2, '0');
197	    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
198	  };
199	
200	  // --- Compact summary stats ---
201	  const todayKey = slotDateKey({ slot_start: new Date().toISOString() });
202	  const stats = {
203	    today: bookings.filter(b => slotDateKey(b) === todayKey).length,
204	    open: bookings.filter(b => b.status === 'Pending' || b.status === 'Confirmed').length,
205	    inProgress: bookings.filter(b => b.status === 'Arrived').length,
206	    closed: bookings.filter(b => CLOSED.includes(b.status)).length,
207	  };
208	
209	  // --- Frontend filtering ---
210	  const q = searchText.trim().toLowerCase();
211	  const filtered = bookings.filter((b) => {
212	    const matchesQ = !q || [b.booking_ref, b.license_plate, b.transport_company, b.driver_name]
213	      .some(v => String(v || '').toLowerCase().includes(q));
214	    const matchesStatus = filterStatus === 'All' || b.status === filterStatus;
215	    const matchesBay = filterBay === 'All' || b.loading_bay === filterBay;
216	    const matchesDate = !filterDate || slotDateKey(b) === filterDate;
217	    return matchesQ && matchesStatus && matchesBay && matchesDate;
218	  });
219	
220	  return (
221	    <div className="dashboard-layout">
222	      <Sidebar />
223	      <main className="dashboard-main">
224	        <header className="dashboard-header">
225	          <div className="header-titles">
226	            <h1>Loading Bay Logistics</h1>
227	            <p>Smart queue management for the {BAYS.length} loading bays — book slots and avoid congestion</p>
228	          </div>
229	          <div className="header-actions">
230	            <button className="edit-btn" onClick={fetchBookings}>Refresh</button>
231	            {canGateScan && (
232	              <button className="edit-btn" onClick={openGate}>Gate Scan</button>
233	            )}
234	            {canCreate && (
235	              <button className="new-booking-btn" onClick={openForm}>+ New Booking</button>
236	            )}
237	          </div>
238	        </header>
239	
240	        {notice && <div className="toast-notification">{notice}</div>}
241	        {error && !isFormOpen && <div className="error-banner" style={{ margin: '0 0 16px' }}>⚠️ {error}</div>}
242	
243	        {/* Compact summary — today's load and the booking pipeline at a glance */}
244	        <div className="logistics-stats">
245	          <div className="logistics-stat-card">
246	            <div className="stat-value">{stats.today}</div>
247	            <div className="stat-label">Today's Bookings</div>
248	          </div>
249	          <div className="logistics-stat-card">
250	            <div className="stat-value">{stats.open}</div>
251	            <div className="stat-label">Pending / Confirmed</div>
252	          </div>
253	          <div className="logistics-stat-card">
254	            <div className="stat-value">{stats.inProgress}</div>
255	            <div className="stat-label">Arrived / In Progress</div>
256	          </div>
257	          <div className="logistics-stat-card">
258	            <div className="stat-value">{stats.closed}</div>
259	            <div className="stat-label">Completed / Cancelled</div>
260	          </div>
261	        </div>
262	
263	        {/* Filters */}
264	        <div className="logistics-toolbar">
265	          <div className="logistics-search">
266	            <input
267	              type="text"
268	              placeholder="Search ref / plate / company / driver..."
269	              value={searchText}
270	              onChange={(e) => setSearchText(e.target.value)}
271	              aria-label="Search bookings"
272	            />
273	          </div>
274	          <select className="logistics-filter" value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} aria-label="Filter by status">
275	            <option value="All">All statuses</option>
276	            {STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
277	          </select>
278	          <select className="logistics-filter" value={filterBay} onChange={(e) => setFilterBay(e.target.value)} aria-label="Filter by bay">
279	            <option value="All">All bays</option>
280	            {BAYS.map(b => <option key={b} value={b}>{b}</option>)}
281	          </select>
282	          <input
283	            type="date"
284	            className="logistics-filter logistics-date"
285	            value={filterDate}
286	            onChange={(e) => setFilterDate(e.target.value)}
287	            aria-label="Filter by slot date"
288	          />
289	          {filterDate && (
290	            <button type="button" className="edit-btn" onClick={() => setFilterDate('')} aria-label="Clear date filter">
291	              Clear date
292	            </button>
293	          )}
294	        </div>
295	
296	        {/* Booking list — plain table styled like Workforce Attendance (no bulky card/heading) */}
297	        <div className="active-bookings">
298	          {loading ? (
299	            <p style={{ padding: '24px', color: '#94a3b8' }}>Loading bookings...</p>
300	          ) : bookings.length === 0 ? (
301	            <p style={{ padding: '24px', color: '#94a3b8' }}>No bookings scheduled yet.</p>
302	          ) : filtered.length === 0 ? (
303	            <p style={{ padding: '24px', color: '#94a3b8' }}>No bookings match your filters.</p>
304	          ) : (
305	            <div className="table-container">
306	              <table className="management-table">
307	                <thead>
308	                  <tr>
309	                    <th>Ref</th><th>Plate</th><th>Company</th><th>Driver</th><th>Bay</th>
310	                    <th>Slot</th><th>Status</th><th>Actions</th>
311	                  </tr>
312	                </thead>
313	                <tbody>
314	                  {filtered.map((b) => {
315	                    const nextStatus = STATUS_FLOW[b.status];
316	                    const isClosed = CLOSED.includes(b.status);
317	                    const canEditOrCancel = !isClosed && (role === 'FM' || role === 'Tenant');
318	                    const hasActions = (canManage && nextStatus) || canEditOrCancel;
319	                    return (
320	                      <tr key={b.id}>
321	                        <td data-label="Ref" className="booking-ref-cell">{b.booking_ref}</td>
322	                        <td data-label="Plate">{b.license_plate}</td>
323	                        <td data-label="Company" className="booking-wrap-cell">{b.transport_company}</td>
324	                        <td data-label="Driver" className="booking-wrap-cell">{b.driver_name || '—'}</td>
325	                        <td data-label="Bay">{b.loading_bay}</td>
326	                        <td data-label="Slot">{fmtSlot(b)}</td>
327	                        <td data-label="Status"><span className={`status-badge ${String(b.status).toLowerCase()}`}>{b.status}</span></td>
328	                        <td data-label="Actions" className="booking-actions-cell">
329	                          {hasActions ? (
330	                            <div className="booking-action-group" aria-label={`Actions for ${b.booking_ref}`}>
331	                              {canManage && nextStatus && (
332	                                <button className="edit-btn booking-action-btn booking-action-primary" onClick={() => updateStatus(b.id, nextStatus)}>
333	                                  Mark {nextStatus}
334	                                </button>
335	                              )}
336	                              {canEditOrCancel && (
337	                                <button className="edit-btn booking-action-btn" onClick={() => openEdit(b)}>
338	                                  Edit
339	                                </button>
340	                              )}
341	                              {canEditOrCancel && (
342	                                <button className="edit-btn booking-action-btn booking-action-danger" onClick={() => cancelBooking(b.id)}>
343	                                  Cancel
344	                                </button>
345	                              )}
346	                            </div>
347	                          ) : (
348	                            <span className="booking-actions-none">—</span>
349	                          )}
350	                        </td>
351	                      </tr>
352	                    );
353	                  })}
354	                </tbody>
355	              </table>
356	            </div>
357	          )}
358	        </div>
359	
360	        {/* Create-booking modal (opens via "+ New Booking") */}
361	        {isFormOpen && canCreate && (
362	          <div className="modal-overlay" onClick={closeForm}>
363	            <div className="modal-content booking-modal" onClick={(e) => e.stopPropagation()}>
364	              <div className="booking-modal-head">
365	                <h2>{editingId ? 'Edit Booking' : 'Schedule New Delivery'}</h2>
366	                <button className="modal-x" onClick={closeForm} aria-label="Close">✕</button>
367	              </div>
368	
369	              {error && <div className="error-banner" style={{ margin: '0 0 14px' }}>⚠️ {error}</div>}
370	
371	              <form onSubmit={submitBookingForm} className="dark-form">
372	                <div className="form-group">
373	                  <label>Transport Company *</label>
374	                  <input name="transport_company" value={form.transport_company} onChange={onField} placeholder="e.g., NinjaVan" required />
375	                </div>
376	                <div className="form-group">
377	                  <label>Vehicle License Plate *</label>
378	                  <input name="license_plate" value={form.license_plate} onChange={onField} placeholder="e.g., GBG 1234M" required />
379	                </div>
380	                <div className="form-group">
381	                  <label>Driver Name</label>
382	                  <input name="driver_name" value={form.driver_name} onChange={onField} placeholder="e.g., Ahmad" />
383	                </div>
384	                <div className="form-group">
385	                  <label>Driver Phone *</label>
386	                  <input name="driver_phone" type="tel" value={form.driver_phone} onChange={onField} placeholder="+65..." required />
387	                </div>
388	                <div className="form-group">
389	                  <label>Loading Bay *</label>
390	                  <select name="loading_bay" value={form.loading_bay} onChange={onField} required>
391	                    <option value="">Select a bay...</option>
392	                    {BAYS.map(b => <option key={b} value={b}>{b}</option>)}
393	                  </select>
394	                </div>
395	                <div className="form-group">
396	                  <label>Slot Start</label>
397	                  <input name="slot_start" type="datetime-local" value={form.slot_start} onChange={onField} />
398	                </div>
399	                <div className="form-group">
400	                  <label>Slot End</label>
401	                  <input name="slot_end" type="datetime-local" value={form.slot_end} onChange={onField} />
402	                </div>
403	                <div className="form-group">
404	                  <label>Notes</label>
405	                  <input name="notes" value={form.notes} onChange={onField} placeholder="Optional" />
406	                </div>
407	                <div className="booking-modal-actions">
408	                  <button type="button" className="cancel-btn" onClick={closeForm}>Cancel</button>
409	                  <button type="submit" className="submit-booking-btn" disabled={submitting}>
410	                    {submitting ? 'Saving...' : editingId ? 'Save Changes' : 'Create Booking'}
411	                  </button>
412	                </div>
413	              </form>
414	            </div>
415	          </div>
416	        )}
417	
418	        {/* Gate Scan modal (FM/Staff) — verify a driver pass at the loading bay */}
419	        {gateOpen && canGateScan && (
420	          <div className="modal-overlay" onClick={closeGate}>
421	            <div className="modal-content booking-modal" onClick={(e) => e.stopPropagation()}>
422	              <div className="booking-modal-head">
