  const early = Number(process.env.GATE_EARLY_MINUTES);
  const late = Number(process.env.GATE_LATE_MINUTES);
  return {
    earlyMin: Number.isFinite(early) ? early : 30,
    lateMin: Number.isFinite(late) ? late : 60,
