    booking_ref: b.booking_ref,
    transport_company: b.transport_company,
    driver_name: b.driver_name,
    license_plate: b.license_plate,
    loading_bay: b.loading_bay,
    slot_start: b.slot_start,
    slot_end: b.slot_end,
    status: b.status,
