  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 2px;
  color: #f8fafc;
  word-break: break-word;
}

/* --- Detail rows --- */
.info-grid {
  background-color: #0b0f1a;
  border: 1px solid #2d364f;
  border-radius: 14px;
  padding: 4px 16px;
  margin-top: 14px;
  text-align: left;
}

.info-item {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 14px;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.info-item:last-child { border-bottom: none; }

.info-item label {
  color: #707a91;
  font-size: 0.8rem;
  font-weight: 500;
  flex: 0 0 auto;
}

.info-item p {
  margin: 0;
  color: #f8fafc;
  font-size: 0.95rem;
  font-weight: 600;
  text-align: right;
  word-break: break-word;
}

.bay-highlight { color: #60a5fa !important; }

/* --- Footer + states --- */
.pass-card footer { margin-top: 18px; }
.pass-card footer p {
  margin: 0;
  color: #64748b;
  font-size: 0.8rem;
  line-height: 1.45;
}

.loader, .error {
  color: #94a3b8;
  text-align: center;
  padding: 48px 8px;
  font-size: 0.95rem;
}
.error { color: #f87171; font-weight: 600; }

/* Hide global floating widgets on the public pass so they don't overlap the ticket. */
